function maskRect(g, x, y, w, h) { return g.rect(w, h).center(x, y).fill('#fff'); }

var RG = draw.group(); // resistor groups for flashing
function resGroup(id) { var g = RG.group().attr('id', id); g.data('fl', g.rect(0, 0).fill('none')); return g; }

var gR1 = resGroup('R1'); maskRect(gR1, 190, top, 130, 30); zigH(gR1, 125, 255, top);
var gR3 = resGroup('R3'); maskRect(gR3, 410, top, 130, 30); zigH(gR3, 345, 475, top);
var gR2 = resGroup('R2'); maskRect(gR2, bx, 185, 30, 130); zigV(gR2, bx, 120, 250);
var gR4 = resGroup('R4'); maskRect(gR4, cx, 185, 30, 130); zigV(gR4, cx, 120, 250);

// batteries
function battery(id, x, y, plusLeft) {
  var g = RG.group().attr('id', id);
  maskRect(g, x, y, 70, 44);
  var s = plusLeft ? 1 : -1; // long plate on + side
  g.line(x - 14 * s, y - 14, x - 14 * s, y + 14).stroke({ color: '#222', width: 2 });   // long
  g.line(x + 12 * s, y - 6, x + 12 * s, y + 6).stroke({ color: '#222', width: 6 });      // short
  g.text('+').font({ size: 15, 'font-family': 'Georgia' }).center(x - 30 * s, y - 24);
  g.text('−').font({ size: 15, 'font-family': 'Georgia' }).center(x + 30 * s, y - 24);
  return g;
}
var gV1 = battery('V1', 190, bot, true);
var gV2 = battery('V2', 410, bot, false);

// labels
function compLabel(txt, x, y) {
  var t = draw.text(txt).font(IT).center(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  return t;
}
compLabel('R₁ = 3.00 Ω', 190, top - 28);
compLabel('R₃ = 3.00 Ω', 410, top - 28);
compLabel('R₂ = 3.00 Ω', bx - 62, 185);
compLabel('R₄ = 4.00 Ω', cx - 68, 185);
compLabel('V₁ = 24.00 V', 190, bot - 38);
compLabel('V₂ = 29.00 V', 410, bot - 38);

var caption = draw.text('(a)').font({ 'font-family': 'Georgia, serif', size: 16 }).center(300, 400);

// labeled mode: teal dots + letters
var labelLayer = draw.group().opacity(0);
var nodes = { a: [ax, top], b: [bx, top], c: [cx, top], f: [ax, bot], e: [bx, bot], d: [cx, bot] };
Object.keys(nodes).forEach(function (k) {
  var p = nodes[k];
  labelLayer.circle(9).center(p[0], p[1]).fill('#1a8a8a');
  var off = (k === 'a') ? [-14, -12] : (k === 'b') ? [0, -18] : (k === 'c') ? [14, -12]
    : (k === 'f') ? [-14, 14] : (k === 'e') ? [0, 22] : [14, 14];
  labelLayer.text(k).font({ 'font-style': 'italic', size: 16, 'font-family': 'Georgia', fill: '#0a5a5a' })
    .center(p[0] + off[0], p[1] + off[1]);
});

// junction mode layer
var jLayer = draw.group().opacity(0);
function hiBranch(pts) {
  jLayer.polyline(pts.map(function (p) { return p.join(','); }).join(' '))
    .fill('none').stroke({ color: '#f0a020', width: 6, opacity: 0.55, linecap: 'round' });
}
function arrow(x1, y1, x2, y2, color, label, lx, ly) {
  var ang = Math.atan2(y2 - y1, x2 - x1), mx = (x1 + x2) / 2, my = (y1 + y2) / 2, s = 8;
  jLayer.line(x1, y1, x2, y2).stroke({ color: color, width: 2.5 });
  jLayer.polygon([[s, 0], [-s, s * 0.7], [-s, -s * 0.7]].map(function (p) {
    return [mx + p[0] * Math.cos(ang) - p[1] * Math.sin(ang), my + p[0] * Math.sin(ang) + p[1] * Math.cos(ang)].join(',');
  }).join(' ')).fill(color);
  jLayer.text(label).font({ 'font-style': 'italic', size: 15, 'font-family': 'Georgia', fill: color }).center(lx, ly);
}
hiBranch([[ax, top], [bx, top]]); hiBranch([[bx, top], [cx, top]]); hiBranch([[bx, top], [bx, bot]]);
arrow(150, top - 14, 260, top - 14, '#c0392b', 'I₁', 205, top - 30);
arrow(340, top - 14, 450, top - 14, '#27ae60', 'I₂', 395, top - 30);
arrow(bx + 16, 110, bx + 16, 240, '#8e44ad', 'I₃', bx + 36, 175);
var jEq = jLayer.text('I₁ = I₂ + I₃').font({ size: 18, 'font-family': 'Georgia, serif', fill: '#333' })
  .center(bx, top + 45);
jEq.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 4 });

// loop trace layer
var traceLayer = draw.group().opacity(0);
var dot = traceLayer.circle(12).fill('#e67e22').stroke({ color: '#fff', width: 2 }).hide();
var eqStrip = draw.group();
var eqX = 90, eqY = 352;

var loops = {
  left: { pts: [[ax, top], [bx, top], [bx, bot], [ax, bot], [ax, top]],
    terms: [{ g: 'R1', t: '−I₁R₁' }, { g: 'R2', t: '−I₃R₂' }, { g: 'V1', t: '+24.0 V' }, null] },
  right: { pts: [[bx, top], [cx, top], [cx, bot], [bx, bot], [bx, top]],
    terms: [{ g: 'R3', t: '−I₂R₃' }, { g: 'R4', t: '−I₄R₄' }, { g: 'V2', t: '−29.0 V' }, { g: 'R2', t: '+I₃R₂' }] }
};
var anim = null, flashes = [];

function clearTrace() {
  if (anim) { cancelAnimationFrame(anim); anim = null; }
  dot.hide(); eqStrip.clear(); eqX = 90;
  flashes.forEach(function (f) { f.remove(); }); flashes = [];
}
function addChip(txt) {
  var t = eqStrip.text(txt).font({ size: 16, 'font-family': 'Georgia, serif', fill: '#333' }).move(eqX, eqY);
  t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3 });
  eqX += t.length() + 16;
}
function flash(id) {
  var g = RG.findOne('#' + id);
  if (!g) return;
  var bb = g.bbox();
  var r = traceLayer.rect(bb.width + 16, bb.height + 16).center(bb.cx, bb.cy)
    .fill('#f0a020').opacity(0.35).radius(6);
  flashes.push(r);
  r.animate(700).opacity(0);
}
function runTrace(which) {
  clearTrace();
  var L = loops[which], segs = [];
  for (var i = 0; i < L.pts.length - 1; i++) {
    var a = L.pts[i], b = L.pts[i + 1];
    segs.push({ a: a, b: b, len: Math.hypot(b[0] - a[0], b[1] - a[1]), term: L.terms[i], fired: false });
  }
  var total = segs.reduce(function (s, x) { return s + x.len; }, 0), speed = 160, d = 0, last = null;
  dot.show();
  function step(ts) {
    if (last == null) last = ts;
    d += (ts - last) / 1000 * speed; last = ts;
    var rem = d, done = true;
    for (var i = 0; i < segs.length; i++) {
      var s = segs[i];
      if (rem <= s.len) {
        var t = rem / s.len;
        dot.center(s.a[0] + (s.b[0] - s.a[0]) * t, s.a[1] + (s.b[1] - s.a[1]) * t);
        if (!s.fired && t > 0.45 && s.term) { s.fired = true; flash(s.term.g); addChip(s.term.t); }
        done = false; break;
      }
      if (!s.fired && s.term) { s.fired = true; flash(s.term.g); addChip(s.term.t); }
      rem -= s.len;
    }
    if (done || d >= total) {
      var p = L.pts[0]; dot.center(p[0], p[1]);
      addChip('ΣΔV = 0'); anim = null; return;
    }
    anim = requestAnimationFrame(step);
  }
  anim = requestAnimationFrame(step);
}

// state
function setLabels(on) {
  labelLayer.animate(400).opacity(on ? 1 : 0);
  caption.text(on ? '(b)' : '(a)');
  document.getElementById('circuitLabelsInput').checked = on;
  if (!on) hideJunction();
}
function toggle_circuitLabels(on) { setLabels(on); }

function hideJunction() { jLayer.animate(300).opacity(0); junctionShown = false; }
var junctionShown = false;
function showJunction(name) {
  setLabels(true);
  jLayer.animate(300).opacity(1); junctionShown = true;
  showPopup('Junction rule at ' + name,
    'Three branches meet at junction ' + name + '. Charge cannot pile up, so the current flowing in equals the current flowing out: I₁ = I₂ + I₃. This is Kirchhoff’s junction rule.');
}
[['b', bx, top], ['e', bx, bot]].forEach(function (n) {
  var hit = draw.circle(26).center(n[1], n[2]).fill('#fff').opacity(0);
  hit.css('cursor', 'pointer');
  hit.on('mousemove', function (e) { showTooltip('junction ' + n[0] + ' — click to apply Kirchhoff’s current rule', e); });
  hit.on('mouseleave', hideTooltip);
  hit.on('click', function () { showJunction(n[0]); });
});

function setLoop(mode) {
  ['idle', 'left', 'right'].forEach(function (m) {
    var btn = document.getElementById('loop' + m[0].toUpperCase() + m.slice(1));
    if (btn) btn.classList.toggle('active', m === mode);
  });
  if (mode === 'idle') { clearTrace(); traceLayer.opacity(0); return; }
  setLabels(true); hideJunction();
  traceLayer.opacity(1);
  runTrace(mode);
}

// demo steps
var steps = [
  { title: 'The bare circuit', narration: 'Panel (a) shows the physical circuit: two loops sharing the middle branch R₂, with V₁ = 24.00 V (+ terminal left) and V₂ = 29.00 V (+ terminal right). Nothing here is labeled yet.',
    run: function () { setLabels(false); setLoop('idle'); hideJunction(); } },
  { title: 'Labels are scaffolding', narration: 'Switching to panel (b) adds teal dots and letters a–f — but not a single component changes. The labels exist only so Kirchhoff’s rules can name places; b and e are the junctions where three wires meet.',
    run: function () { setLabels(true); setLoop('idle'); hideJunction(); } },
  { title: 'Junction rule', narration: 'Click junction b (or e): its three branches highlight, current arrows appear, and the junction equation I₁ = I₂ + I₃ states that whatever current flows in must flow back out.',
    run: function () { setLabels(true); setLoop('idle'); jLayer.opacity(1); junctionShown = true; } },
  { title: 'Loop rule — left loop', narration: 'Trace the left loop a→b→e→f→a: each element lights in traversal order — a drop I₁R₁ across R₁, a drop I₃R₂ down R₂, a rise of V₁ = 24 V through the battery — building an equation that sums to zero.',
    run: function () { setLoop('left'); } },
  { title: 'Loop rule — right loop', narration: 'Trace the right loop b→c→d→e→b: the shared branch R₂ now contributes a term of the opposite sign because traversal goes against I₃, and V₂ enters as a drop crossed from + to − — loop direction sets the signs.',
    run: function () { setLoop('right'); } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  document.getElementById('demoNarration').textContent = steps[stepIdx].title + ' — ' + steps[stepIdx].narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + '/' + steps.length;
  steps[stepIdx].run();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Kirchhoff's rules turn one multi-loop circuit into solvable equations: at each junction the currents balance, and around any closed loop the signed voltage rises and drops sum to zero — node labels a–f are bookkeeping laid over an unchanged physical circuit.
KEY INSIGHT (what students should walk away understanding): The labels a–f change nothing physically — they exist so Kirchhoff's two rules can be written down: currents balance at junctions b and e (I1 = I2 + I3), and signed voltage changes sum to zero around either loop.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Kirchhoff's rules turn one multi-loop circuit into solvable equations: at each junction the currents balance, and around any closed loop the signed voltage rises and drops sum to zero — node labels a–f are bookkeeping laid over an unchanged physical circuit.",
  "figureType": "diagram",
  "elements": [
    "single rectangular circuit frame split by a center vertical branch into two loops (the interactive shows one drawing whose caption swaps between (a) and (b) instead of two side-by-side panels)",
    "resistor R1 = 3.00 Ω (blue zigzag) on the top wire of the left loop, between a and b",
    "resistor R3 = 3.00 Ω (blue zigzag) on the top wire of the right loop, between b and c",
    "resistor R2 = 3.00 Ω (blue zigzag) on the shared center branch, between b and e",
    "resistor R4 = 4.00 Ω (blue zigzag) on the right vertical branch, between c and d",
    "plain left vertical wire between a and f",
    "battery V1 = 24.00 V on the bottom wire of the left loop, + terminal on the left",
    "battery V2 = 29.00 V on the bottom wire of the right loop, + terminal on the right",
    "six teal node dots at a, b, c (top) and f, e, d (bottom), visible in labeled mode",
    "node letters a, b, c, d, e, f beside their dots, visible in labeled mode",
    "caption '(a)' or '(b)' beneath the circuit, matching the toggle",
    "current arrows labeled I1, I2, I3 on the three branches meeting at the selected junction (junction mode)",
    "junction equation annotation 'I1 = I2 + I3' (junction mode)",
    "loop-trace traversal highlight that visits each element in order (loop mode)",
    "equation strip accumulating signed voltage terms and ending in 'ΣΔV = 0' (loop mode)"
  ],
  "interactions": [
    {
      "id": "circuitLabels",
      "type": "toggle",
      "label": "Circuit view",
      "options": [
        "Unlabeled (a)",
        "Labeled (b)"
      ],
      "default": "Unlabeled (a)",
      "teaches": "Node dots and letters are analysis scaffolding laid over the same physical circuit — toggling shows that every resistor, battery, and wire is identical; only the naming needed for Kirchhoff's rules is added"
    },
    {
      "id": "junctionClick",
      "type": "click",
      "teaches": "At a junction the currents in the three connected branches must balance — clicking b or e highlights those branches, draws current arrows, and shows I1 = I2 + I3 (current in equals current out)"
    },
    {
      "id": "loopTrace",
      "type": "state",
      "label": "Loop tracing",
      "states": [
        "idle",
        "left loop",
        "right loop"
      ],
      "default": "idle",
      "teaches": "Walking a closed loop in one direction assigns each element a signed term — a rise across a battery traversed − to +, a drop across a resistor traversed with the current (a rise against it) — and the accumulated terms must total zero"
    }
  ],
  "demo_steps": [
    {
      "title": "The bare circuit",
      "narration": "Panel (a) shows the physical circuit: two loops sharing the middle branch R2, with V1 = 24.00 V (+ terminal left) in the left loop and V2 = 29.00 V (+ terminal right) in the right loop. Nothing here is labeled yet.",
      "state": {
        "circuitLabels": "Unlabeled (a)",
        "loopTrace": "idle"
      }
    },
    {
      "title": "Labels are scaffolding",
      "narration": "Switching to panel (b) adds teal dots and letters a–f at the corners and branch points — but not a single component changes. The labels exist only so Kirchhoff's rules can name places; b and e are the junctions where three wires meet.",
      "state": {
        "circuitLabels": "Labeled (b)",
        "loopTrace": "idle"
      }
    },
    {
      "title": "Junction rule",
      "narration": "Click junction b (or e): its three branches highlight, current arrows appear, and the junction equation I1 = I2 + I3 states that whatever current flows in must flow back out.",
